  ('8b4df5a1-6811-576b-bbe7-351d40bd3324', '4fdfea61-47aa-5ba1-ba2d-6037a97e68f1', 'ad3b70aa-6a6d-5c16-a41d-fc3fc64f2ef3', 1, 'Number of target provinces participating in policy implementation.', 'ចំនួនខេត្តគោលដៅចូលរួមអនុវត្តគោលនយោបាយ', 'count', 'count_to_target', 'increase', 'if(${ind_008_value} != '''', round((${ind_008_value} div 8) * 100), '''')', 'annual', 'Ministry annual report (Kobo)', '2025-01-01', false),
  ('dd12b3f7-de87-5337-a2f9-6bfa9d7d2a0f', '4fdfea61-47aa-5ba1-ba2d-6037a97e68f1', '05f7dfa9-10b8-5190-8c29-efb93a178b24', 1, 'Number of business owners participating in the implementation of the Chakra strategy.', 'ម្ចាស់អាជីវកម្មចូលរួមអនុវត្តយុទ្ធសាស្រ្តចក្រា', 'count', 'count_to_target', 'increase', 'if(${ind_009_value} != '''', round((${ind_009_value} div 50) * 100), '''')', 'annual', 'Ministry annual report (Kobo)', '2025-01-01', false),
